import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { useMedicalIncidentPermissions } from '../../hooks/useMedicalIncidentPermissions';
import {
  fetchMedicalIncidents,
  fetchMedicalIncidentStats,
  setFilters,
  setPage,
  deleteMedicalIncident,
} from '../../store/slices/medicalIncidentsSlice';
import { scykRoutes } from '../../config/scykRoutes';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { useFormOptions } from '../../hooks/useFormOptions';
import { currentYearDateRange } from '../../hooks/useReportPeriodFilter';
import { MedicalIncidentStatsCards } from './components/MedicalIncidentStatsCards';
import { MedicalIncidentFiltersBar } from './components/MedicalIncidentFiltersBar';
import { MedicalIncidentTable } from './components/MedicalIncidentTable';
import { MedicalIncident, MedicalIncidentFilters, IncidentStatus, IncidentSeverity, IncidentReportType, INCIDENT_LIST_STATUS_EXTRA } from '../../models/MedicalIncident';
import { IncidentPrintModal } from '../../components/shared';
import { medicalIncidentService } from '../../services/medicalIncidents';
import { ImportIncidentsModal } from './components/ImportIncidentsModal/ImportIncidentsModal';
import { BatchStatusBar } from './components/BatchStatusBar';
import { useExportExcel } from '../../hooks/useExportExcel';
import { useResponsive } from '../../hooks/useResponsive';
import { addToast } from '../../store/slices/uiSlice';
import { formatIncidentListStatusLabel } from '../../utils/incidentListStatusFilter';
import styles from './MedicalIncidentsListPage.module.css';

import { Button, TableCard, Pagination, ExportConfirmModal } from '@linm-soft-org/linm-web-common-components';
const MedicalIncidentsListPage: React.FC = () => {
  const appNavigate = useAppNavigate();
  const location    = useLocation();
  const dispatch    = useAppDispatch();
  const { isMobile } = useResponsive();

  const { items, loading, statsLoading, filters, pagination, stats } = useAppSelector(
    (s) => s.medicalIncidents,
  );
  const {
    canRead,
    canCreate,
    canExport,
    canImport,
    canBatchStatus,
    canDelete,
    isReporterScope,
  } = useMedicalIncidentPermissions();

  // Keep skeleton visible for at least 300 ms to avoid flash-of-loading.
  const showLoading = useMinLoadingTime(loading);

  const { incidentStatusOptions, incidentSeverityOptions } = useFormOptions('incident-list');

  const [deleteConfirm,    setDeleteConfirm]    = useState<MedicalIncident | null>(null);
  const [printTarget,      setPrintTarget]      = useState<MedicalIncident | null>(null);
  const [showExportModal,  setShowExportModal]  = useState(false);
  const [showImportModal,  setShowImportModal]  = useState(false);
  const [selectedIds,      setSelectedIds]      = useState<string[]>([]);
  const [selectAllLoading, setSelectAllLoading] = useState(false);
  const [batchSaving, setBatchSaving] = useState(false);
  const { exportExcel } = useExportExcel();

  // ── Export columns definition (shared between current-page & all exports) ──
  const exportColumns = [
    { key: 'no',             label: 'STT',               width: 6  },
    { key: 'idCode',         label: 'Mã sự cố',          width: 16 },
    { key: 'incidentName',   label: 'Tên sự cố',         width: 28 },
    { key: 'briefDescription', label: 'Mô tả sự cố',     width: 36 },
    { key: 'patientCode',    label: 'Mã bệnh nhân',      width: 16 },
    { key: 'patientName',    label: 'Tên bệnh nhân',     width: 24 },
    { key: 'reportingDepartmentName', label: 'Khoa báo cáo',  width: 22 },
    { key: 'severity',       label: 'Mức độ',            width: 12 },
    { key: 'status',         label: 'Trạng thái',        width: 16 },
    { key: 'occurredAt',     label: 'Thời điểm xảy ra',  width: 20 },
    { key: 'createdByName',  label: 'Người tạo',         width: 22 },
    { key: 'createdAt',      label: 'Ngày tạo',          width: 18 },
  ];

  const exportRows = items.map((item, idx) => ({
    no:             idx + 1 + (pagination.page - 1) * pagination.pageSize,
    idCode:         item.idCode         ?? '',
    incidentName:   item.incidentName   ?? '',
    briefDescription: item.briefDescription ?? '',
    patientCode:    item.patientCode    ?? '',
    patientName:    item.patientName    ?? '',
    reportingDepartmentName: item.reportingDepartmentName ?? '',
    severity:       incidentSeverityOptions.find((o) => o.value === item.severity)?.label ?? item.severity ?? '',
    status:         formatIncidentListStatusLabel(item, incidentStatusOptions),
    occurredAt:     item.occurredAt     ?? '',
    createdByName:  item.createdByName  ?? '',
    createdAt:      item.createdAt      ?? '',
  }));

  /** Download blob as a file in the browser */
  const triggerBlobDownload = (blob: Blob, fileName: string) => {
    const url = URL.createObjectURL(blob);
    const a   = document.createElement('a');
    a.href     = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportAll = async () => {
    const blob     = await medicalIncidentService.exportAll(filters);
    const today    = new Date().toISOString().slice(0, 10);
    triggerBlobDownload(blob, `SuCoYKhoa_${today}.xlsx`);
  };

  // Apply URL params as initial filters (e.g. navigating from Report charts)
  useEffect(() => {
    const timer = setTimeout(() => {
      const params       = new URLSearchParams(location.search);
      const reportingDepartmentId =
        params.get('reportingDepartmentId') ?? params.get('departmentId') ?? undefined;
      const dateFrom     = params.get('dateFrom')     ?? undefined;
      const dateTo       = params.get('dateTo')       ?? undefined;
      const reportType   = (params.get('reportType')  ?? undefined) as IncidentReportType | undefined;
      const severity     = (params.get('severity')    ?? undefined) as IncidentSeverity   | undefined;
      if (reportingDepartmentId || dateFrom || dateTo || reportType || severity) {
        dispatch(setFilters({ ...filters, reportingDepartmentId, dateFrom, dateTo, reportType, severity }));
      }
    }, 0);
    return () => clearTimeout(timer);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.search]);
  useEffect(() => {
    setSelectedIds([]);
    const timer = setTimeout(() => { dispatch(fetchMedicalIncidents()); }, 0);
    return () => clearTimeout(timer);
  }, [dispatch, filters, pagination.page]);

  // Re-fetch stats whenever scope-affecting filters change.
  // Status / severity / search changes do NOT re-fetch stats — they only filter the list.
  useEffect(() => {
    const timer = setTimeout(() => { dispatch(fetchMedicalIncidentStats()); }, 0);
    return () => clearTimeout(timer);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dispatch, filters.reportingDepartmentId, filters.dateFrom, filters.dateTo, filters.isServiceMismatch, filters.hasFall]);

  /** Derive which stats card is 'active' from the current Redux filters. */
  const activeStatsFilter = (() => {
    if (filters.severity === IncidentSeverity.Severe) return 'severe';
    if (
      filters.status === INCIDENT_LIST_STATUS_EXTRA.notMedicalIncident ||
      filters.isNotMedicalIncident === true
    ) {
      return 'notMedicalIncident';
    }
    if (
      filters.status &&
      filters.status !== INCIDENT_LIST_STATUS_EXTRA.serviceMismatch
    ) {
      return filters.status;
    }
    return 'all';
  })();

  /**
   * When a stats card is clicked, apply the matching filter.
   * Clicking the already-active card toggles it off (→ 'all').
   */
  const handleStatsCardFilter = (key: string) => {
    if (key === 'all' || key === activeStatsFilter) {
      // Reset status/severity filters, keep any other filters (e.g. search)
      dispatch(setFilters({
        ...filters,
        status: undefined,
        severity: undefined,
        isNotMedicalIncident: undefined,
        isServiceMismatch: undefined,
      }));
    } else if (key === 'severe') {
      dispatch(setFilters({
        ...filters,
        severity: IncidentSeverity.Severe,
        status: undefined,
        isNotMedicalIncident: undefined,
        isServiceMismatch: undefined,
      }));
    } else if (key === 'notMedicalIncident') {
      dispatch(setFilters({
        ...filters,
        status: INCIDENT_LIST_STATUS_EXTRA.notMedicalIncident,
        severity: undefined,
        isServiceMismatch: undefined,
      }));
    } else {
      dispatch(setFilters({
        ...filters,
        status: key as IncidentStatus,
        severity: undefined,
        isNotMedicalIncident: undefined,
        isServiceMismatch: undefined,
      }));
    }
    // setFilters already resets page to 1 in the slice reducer.
  };

  const handleFilterChange = (f: MedicalIncidentFilters) => {
    dispatch(setFilters(f));
    dispatch(setPage(1));
  };

  const handleClearFilters = () => {
    const year = currentYearDateRange();
    dispatch(setFilters({ dateFrom: year.dateFrom, dateTo: year.dateTo }));
    dispatch(setPage(1));
  };

  const handleCreate = () => appNavigate(scykRoutes.incidents.new);

  const handleImportComplete = ({ successCount, hasErrors }: { successCount: number; hasErrors: boolean }) => {
    if (!hasErrors) {
      setShowImportModal(false);
    }
    if (successCount > 0) {
      dispatch(fetchMedicalIncidents());
      dispatch(fetchMedicalIncidentStats());
      dispatch(addToast({
        type: hasErrors ? 'warning' : 'success',
        message: hasErrors
          ? `Đã nhập ${successCount} bản ghi. Còn bản ghi lỗi — vui lòng kiểm tra trong modal.`
          : `Đã nhập thành công ${successCount} bản ghi`,
      }));
    }
  };

  const handleSelectAllFiltered = async () => {
    if (pagination.totalCount === 0) return;
    if (selectedIds.length === pagination.totalCount) {
      setSelectedIds([]);
      return;
    }
    setSelectAllLoading(true);
    try {
      const ids = await medicalIncidentService.getAllIds(filters);
      setSelectedIds(ids);
    } catch {
      dispatch(addToast({ type: 'error', message: 'Không thể tải danh sách chọn. Vui lòng thử lại.' }));
    } finally {
      setSelectAllLoading(false);
    }
  };

  const handleView = (item: MedicalIncident) =>
    appNavigate(scykRoutes.incidents.detail(item.id));

  const handleEdit = (item: MedicalIncident) =>
    appNavigate(scykRoutes.incidents.detail(item.id));

  const handleDeleteConfirm = async () => {
    if (!deleteConfirm) return;
    await dispatch(deleteMedicalIncident(deleteConfirm.id));
    setDeleteConfirm(null);
    dispatch(fetchMedicalIncidentStats());
  };

  const handleBatchStatusUpdate = async (status: IncidentStatus) => {
    if (selectedIds.length === 0) return;
    setBatchSaving(true);
    try {
      await medicalIncidentService.batchUpdateStatusInChunks(selectedIds, status);
      dispatch(fetchMedicalIncidents());
      dispatch(addToast({ type: 'success', message: `Đã cập nhật trạng thái ${selectedIds.length} sự cố` }));
      setSelectedIds([]);
      dispatch(fetchMedicalIncidentStats());
    } catch {
      dispatch(addToast({ type: 'error', message: 'Cập nhật trạng thái thất bại. Vui lòng thử lại.' }));
    } finally {
      setBatchSaving(false);
    }
  };

  return (
    <div className={styles.page}>
      {/* Header: title left, action buttons right — single compact row */}
      <div className={styles.pageHeader}>
        <h1 className={styles.title}>
          <i className="fas fa-hospital-user" />
          {!isMobile && ' Quản lý sự cố y khoa'}
        </h1>
        <div className={styles.headerActions}>
          {canExport && (
            <Button variant="secondary" onClick={() => setShowExportModal(true)} disabled={pagination.totalCount === 0}>
              <i className="fas fa-file-excel" />
              {!isMobile && ' Xuất Excel'}
            </Button>
          )}
          {canImport && (
            <Button variant="secondary" onClick={() => setShowImportModal(true)}>
              <i className="fas fa-file-import" />
              {!isMobile && ' Nhập từ file'}
            </Button>
          )}
          {canCreate && (
            <Button variant="primary" onClick={handleCreate}>
              <i className="fas fa-plus" />
              {!isMobile && ' Thêm sự cố'}
            </Button>
          )}
        </div>
      </div>

      {/* Scoped list hint — STAFF / reporter scope only (BE filters createdById) */}
      {isReporterScope && (
        <div className={styles.roleBanner}>
          <i className="fas fa-user-shield" />
          <span>Danh sách <strong>sự cố do bạn tạo</strong>.</span>
        </div>
      )}

      {/* Stats */}
      <MedicalIncidentStatsCards
        stats={stats}
        loading={statsLoading}
        activeFilter={activeStatsFilter}
        onFilter={handleStatsCardFilter}
      />

      {/* Batch status bar — visible when ≥1 row is selected */}
      {canBatchStatus && selectedIds.length > 0 && (
        <BatchStatusBar
          selectedCount={selectedIds.length}
          totalFilteredCount={pagination.totalCount}
          statusOptions={incidentStatusOptions}
          saving={batchSaving}
          onConfirm={handleBatchStatusUpdate}
          onClear={() => setSelectedIds([])}
        />
      )}

      {/* Table card */}
      <TableCard
        header={
          <MedicalIncidentFiltersBar
            filters={filters}
            onChange={handleFilterChange}
            onClear={handleClearFilters}
            loading={showLoading}
          />
        }
        footer={
          <Pagination
            currentPage={pagination.page}
            totalPages={Math.ceil(Math.max(pagination.totalCount, 1) / pagination.pageSize)}
            totalCount={pagination.totalCount}
            pageSize={pagination.pageSize}
            onPageChange={(p) => dispatch(setPage(p))}
          />
        }
      >
        <MedicalIncidentTable
          items={items}
          loading={showLoading}
          statusOptions={incidentStatusOptions}
          severityOptions={incidentSeverityOptions}
          selectedIds={selectedIds}
          totalFilteredCount={pagination.totalCount}
          selectAllLoading={selectAllLoading}
          enableSelection={canBatchStatus}
          canDelete={canDelete}
          canPrint={canRead}
          onSelectionChange={canBatchStatus ? setSelectedIds : undefined}
          onSelectAllFiltered={canBatchStatus ? handleSelectAllFiltered : undefined}
          onView={handleView}
          onEdit={handleEdit}
          onDelete={(item) => setDeleteConfirm(item)}
          onDownloadPdf={(item) => setPrintTarget(item)}
        />
      </TableCard>

      {/* Print / PDF modal */}
      {printTarget && (
        <IncidentPrintModal
          isOpen
          onClose={() => setPrintTarget(null)}
          incident={printTarget}
        />
      )}

      {/* Import modal */}
      <ImportIncidentsModal
        isOpen={showImportModal}
        onClose={() => setShowImportModal(false)}
        onImportComplete={handleImportComplete}
      />

      {/* Export confirm modal */}
      <ExportConfirmModal
        isOpen={showExportModal}
        onClose={() => setShowExportModal(false)}
        currentPageCount={items.length}
        totalCount={pagination.totalCount}
        onExportCurrent={() => {
          exportExcel({
            fileName:  'SuCoYKhoa',
            sheetName: 'Sự Cố Y Khoa',
            columns:   exportColumns,
            rows:      exportRows,
          });
        }}
        onExportAll={handleExportAll}
      />

      {/* Delete confirmation dialog */}
      {deleteConfirm && (
        <div className={styles.overlay}>
          <div className={styles.dialog}>
            <h3>Xác nhận xóa</h3>
            <p>
              Bạn có chắc muốn xóa sự cố{' '}
              <strong>{deleteConfirm.idCode}</strong>?<br />
              Hành động này không thể hoàn tác.
            </p>
            <div className={styles.dialogActions}>
              <Button variant="secondary" onClick={() => setDeleteConfirm(null)}>
                Hủy
              </Button>
              <Button variant="danger" onClick={handleDeleteConfirm}>
                <i className="fas fa-trash" /> Xóa
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MedicalIncidentsListPage;
